pub fn glyph(code: u8) []const Run {
    if (code < first or code > last) return glyphs[0].runs;
    return glyphs[code - first].runs;
}

pub fn advance(count: usize, scale: f32) f32 {
    return @as(f32, @floatFromInt(count)) * @as(f32, @floatFromInt(cell)) * scale;
}

test "press start glyphs cover printable ascii" {
    const std = @import("std");
    try std.testing.expectEqual(@as(usize, 95), glyphs.len);
    try std.testing.expectEqual(@as(usize, 0), glyph(' ').len);
    try std.testing.expect(glyph('A').len > 0);
    try std.testing.expect(glyph('0').len > 0);
    try std.testing.expectEqual(@as(f32, 16), advance(2, 1));
}
